-- DC: Jade Forest (map 745) pandaren guards - varied composited displays + weapons.
-- Generated by Custom/Custom feature SQLs/worlddb/JadeForestGuards/tools/gen_jade_guards.py
-- "Panda Bruiser" 800021 + clones 800035, 800036, 800037: 16 displays (was 1 critter model), 16 random weapon sets. Idempotent - safe to re-run.
-- The matching client DBC rows are in Custom/CSV DBC (CreatureDisplayInfo, CreatureDisplayInfoExtra).

-- Server-side DBC overlay rows
DELETE FROM `creaturedisplayinfoextra_dbc` WHERE `ID` BETWEEN 503726 AND 503741;

DELETE FROM `creaturedisplayinfo_dbc` WHERE `ID` BETWEEN 505151 AND 505166;

-- creature_model_info (without it the spawn refuses to load)
DELETE FROM `creature_model_info` WHERE `DisplayID` BETWEEN 505151 AND 505166;

-- Clones of 800021 (creature_template_model caps an entry at 4 displays)
-- Intended linter flag ("No DELETE before INSERT"): creature_template may not be DELETEd, so this
-- INSERT is made idempotent with NOT EXISTS instead.
SELECT `c`.`e`, `t`.`difficulty_entry_1`, `t`.`difficulty_entry_2`, `t`.`difficulty_entry_3`, `t`.`KillCredit1`, `t`.`KillCredit2`, `t`.`name`, `t`.`subname`, `t`.`IconName`, `t`.`gossip_menu_id`, `t`.`minlevel`, `t`.`maxlevel`, `t`.`exp`, `t`.`faction`, `t`.`npcflag`, `t`.`speed_walk`, `t`.`speed_run`, `t`.`speed_swim`, `t`.`speed_flight`, `t`.`detection_range`, `t`.`rank`, `t`.`dmgschool`, `t`.`DamageModifier`, `t`.`BaseAttackTime`, `t`.`RangeAttackTime`, `t`.`BaseVariance`, `t`.`RangeVariance`, `t`.`unit_class`, `t`.`unit_flags`, `t`.`unit_flags2`, `t`.`dynamicflags`, `t`.`family`, `t`.`type`, `t`.`type_flags`, `t`.`lootid`, `t`.`pickpocketloot`, `t`.`skinloot`, `t`.`PetSpellDataId`, `t`.`VehicleId`, `t`.`mingold`, `t`.`maxgold`, `t`.`AIName`, `t`.`MovementType`, `t`.`HoverHeight`, `t`.`HealthModifier`, `t`.`ManaModifier`, `t`.`ArmorModifier`, `t`.`ExperienceModifier`, `t`.`RacialLeader`, `t`.`movementId`, `t`.`RegenHealth`, `t`.`CreatureImmunitiesId`, `t`.`flags_extra`, `t`.`ScriptName`, `t`.`VerifiedBuild` FROM `creature_template` `t` JOIN (SELECT 800035 AS `e` UNION ALL SELECT 800036 AS `e` UNION ALL SELECT 800037 AS `e`) `c`
WHERE `t`.`entry` = 800021 AND NOT EXISTS (SELECT 1 FROM `creature_template` `x` WHERE `x`.`entry` = `c`.`e`);

-- Display pools: 4 variants per entry, every variant equally likely. Variant k goes to entry k % 4, so each entry mixes plate, mail, light and female guards.
DELETE FROM `creature_template_model` WHERE `CreatureID` IN (800021, 800035, 800036, 800037);

-- Weapons: every entry gets all sets, picked at random per spawn (creature.equipment_id = -1)
DELETE FROM `creature_equip_template` WHERE `CreatureID` IN (800021, 800035, 800036, 800037);

-- Deal the spawns round-robin across the four entries, then give all of them random weapons
UPDATE `creature` SET `id` = 800021 WHERE `id` IN (800021, 800035, 800036, 800037) AND `guid` IN (9000113, 9000122, 9000129, 9001517, 9001530, 9001534, 9001563);
UPDATE `creature` SET `id` = 800035 WHERE `id` IN (800021, 800035, 800036, 800037) AND `guid` IN (9000114, 9000123, 9000814, 9001526, 9001531, 9001535);
UPDATE `creature` SET `id` = 800036 WHERE `id` IN (800021, 800035, 800036, 800037) AND `guid` IN (9000116, 9000124, 9000815, 9001527, 9001532, 9001536);
UPDATE `creature` SET `id` = 800037 WHERE `id` IN (800021, 800035, 800036, 800037) AND `guid` IN (9000117, 9000125, 9001516, 9001528, 9001533, 9001537);
UPDATE `creature` SET `equipment_id` = -1 WHERE `id` IN (800021, 800035, 800036, 800037) AND `guid` IN (
9000113, 9000114, 9000116, 9000117, 9000122, 9000123, 9000124, 9000125, 9000129, 9000814,
9000815, 9001516, 9001517, 9001526, 9001527, 9001528, 9001530, 9001531, 9001532, 9001533,
9001534, 9001535, 9001536, 9001537, 9001563);
